def _gettarget(self, sys_path):
    # type: (Text) -> Optional[Text]
    if hasattr(os, "readlink"):
        try:
            if _WINDOWS_PLATFORM:  # pragma: no cover
                return os.readlink(sys_path)
            else:
                return fsdecode(os.readlink(fsencode(sys_path)))
        except OSError:
            pass
    return None

