        raise ValueError("invalid value for whence")
    with self._lock:
        if _whence == Seek.set:
            new_pos = pos
        elif _whence == Seek.current:
            new_pos = self.pos + pos
        elif _whence == Seek.end:
            file_size = self.fs.getsize(self.path)
            new_pos = file_size + pos
        self.pos = max(0, new_pos)

        self.ftp.quit()
