    if not _path:
        raw_info["basic"] = {"name": "", "is_dir": True}
        if "details" in namespaces:
            raw_info["details"] = {"type": int(ResourceType.directory)}

    else:
        try:
            implicit = False
            member = self._directory_entries[_path]
        except KeyError:
            if not self.isdir(_path):
                raise errors.ResourceNotFound(path)
            implicit = True
            member = tarfile.TarInfo(_path)
            member.type = tarfile.DIRTYPE

        raw_info["basic"] = {
            "name": basename(self._decode(member.name)),
            "is_dir": member.isdir(),
        }

        if "details" in namespaces:
            raw_info["details"] = {
                "size": member.size,
                "type": int(self.type_map[member.type]),
            }
            if not implicit:
                raw_info["details"]["modified"] = member.mtime
        if "access" in namespaces and not implicit:
            raw_info["access"] = {
                "gid": member.gid,
                "group": member.gname,
                "permissions": Permissions(mode=member.mode).dump(),
                "uid": member.uid,
                "user": member.uname,
            }
        if "tar" in namespaces and not implicit:
            raw_info["tar"] = _get_member_info(member, self.encoding)
            raw_info["tar"].update(
                {
                    k.replace("is", "is_"): getattr(member, k)()
                    for k in dir(member)
                    if k.startswith("is")
                }
            )

    return Info(raw_info)

def isdir(self, path):
    _path = relpath(self.validatepath(path))
    try:
        return self._directory_entries[_path].isdir()
    except KeyError:
        return any(isbase(_path, name) for name in self._directory_entries)

def isfile(self, path):
    _path = relpath(self.validatepath(path))
    try:
        return self._directory_entries[_path].isfile()
    except KeyError:
        return False

def __eq__(self, other):
    # type: (object) -> bool
    return self.raw == getattr(other, "raw", None)

def __eq__(self, other):
    # type: (object) -> bool
    if isinstance(other, Permissions):
        names = other.dump()  # type: object
    else:
        names = other
    return self.dump() == names

def __ne__(self, other):
    # type: (object) -> bool
    return not self.__eq__(other)

def dump(self):
    # type: () -> List[Text]
    """Get a list suitable for serialization."""
    return sorted(self._perms)

def _make_datetime(self, t):  # noqa: F811
    # type: (Optional[int]) -> Optional[datetime]
    if t is not None:
        return self._to_datetime(t)
    else:
        return None

def datetime_to_epoch(d):
    # type: (datetime) -> int
    """Convert datetime to epoch."""
    return timegm(d.utctimetuple())

def epoch_to_datetime(t):
    # type: (Optional[int]) -> Optional[datetime]
    """Convert epoch time to a UTC datetime."""
    if t is None:
        return None
    return datetime.fromtimestamp(t, tz=timezone.utc)

def is_dir(self):
    # type: () -> bool
    """`bool`: `True` if the resource references a directory."""
    return cast(bool, self.get("basic", "is_dir"))

def is_file(self):
    # type: () -> bool
    """`bool`: `True` if the resource references a file."""
    return not cast(bool, self.get("basic", "is_dir"))

def count_lines(self):
    # type: () -> LineCounts
    """Count the lines in the matched files.

    Returns:
        `~LineCounts`: A named tuple containing line counts.

    Example:
        >>> my_fs.glob('**/*.py').count_lines()
        LineCounts(lines=4, non_blank=3)

    """
    lines = 0
    non_blank = 0
    for path, info in self._make_iter():
        if info.is_file:
            for line in self.fs.open(path, "rb"):
                lines += 1
                if line.rstrip():
                    non_blank += 1
    return LineCounts(lines=lines, non_blank=non_blank)

def parse(lines):
    info = []
    for line in lines:
        if not line.strip():
            continue
        raw_info = parse_line(line)
        if raw_info is not None:
            info.append(raw_info)
    return info

def parse_line(line):
    for line_re, decode_callable in get_decoders():
        match = line_re.match(line)
        if match is not None:
            return decode_callable(line, match)
    return None

def iterate_fs(self):
    # type: () -> Iterator[Tuple[Text, FS]]
    """Get iterator that returns (name, fs) in priority order."""
    if self._fs_sequence is None:
        self._fs_sequence = [
            (name, fs)
            for name, (_order, fs) in sorted(
                self._filesystems.items(), key=itemgetter(1), reverse=True
            )
        ]
    return iter(self._fs_sequence)

def which(self, path, mode="r"):
    # type: (Text, Text) -> Tuple[Optional[Text], Optional[FS]]
    """Get a tuple of (name, fs) that the given path would map to.

    Arguments:
        path (str): A path on the filesystem.
        mode (str): An `io.open` mode.

    """
    if check_writable(mode):
        return self._write_fs_name, self.write_fs
    for name, fs in self.iterate_fs():
        if fs.exists(path):
            return name, fs
    return None, None

def listdir(self, path):
    # type: (Text) -> List[Text]
    self.check()
    directory = []
    exists = False
    for _name, _fs in self.iterate_fs():
        try:
            directory.extend(_fs.listdir(path))
        except errors.ResourceNotFound:
            pass
        else:
            exists = True
    if not exists:
        raise errors.ResourceNotFound(path)
    directory = list(OrderedDict.fromkeys(directory))
    return directory

def _delegate(self, path):
    # type: (Text) -> Optional[FS]
    """Get a filesystem which has a given path."""
    for _name, fs in self.iterate_fs():
        if fs.exists(path):
            return fs
    return None

def readbytes(self, path):
    # type: (Text) -> bytes
