def close(self):
    # type: () -> None
    if not self.isclosed():
        try:
            self.write_tar()
        finally:
            self._temp_fs.close()
    super(WriteTarFS, self).close()

def __repr__(self):
    # type: () -> Text
    return "ReadTarFS({!r})".format(self._file)

def _list_tar():
    for name, info in _directory_entries:
        try:
            _name = normpath(name)
        except IllegalBackReference:
            # Back references outside root, must be up to no good.
            pass
        else:
            if _name:
                yield _name, info

def getinfo(self, path, namespaces=None):
    # type: (Text, Optional[Collection[Text]]) -> Info
    self.check()
    _fs, _path = self.delegate_path(path)
    with unwrap_errors(path):
        raw_info = _fs.getinfo(_path, namespaces=namespaces).raw
    if abspath(normpath(path)) == "/":
        raw_info = dict(raw_info)
        raw_info["basic"]["name"] = ""  # type: ignore
    return Info(raw_info)

def setinfo(self, path, info):
    # type: (Text, RawInfo) -> None
    self.check()
