    return _fs.setinfo(_path, info)

def copydir(self, src_path, dst_path, create=False, preserve_time=False):
    # type: (Text, Text, bool, bool) -> None
    src_fs, _src_path = self.delegate_path(src_path)
    dst_fs, _dst_path = self.delegate_path(dst_path)
    with unwrap_errors({_src_path: src_path, _dst_path: dst_path}):
        if not create and not dst_fs.exists(_dst_path):
            raise errors.ResourceNotFound(dst_path)
        if not src_fs.getinfo(_src_path).is_dir:
            raise errors.DirectoryExpected(src_path)
        copy_dir(src_fs, _src_path, dst_fs, _dst_path, preserve_time=preserve_time)

def _copy_locked():
    if dst_fs.hassyspath(dst_path):
        with dst_fs.openbin(dst_path, "w") as write_file:
            src_fs.download(src_path, write_file)
    else:
        with src_fs.openbin(src_path) as read_file:
            dst_fs.upload(dst_path, read_file)

    if preserve_time:
        copy_modified_time(src_fs, src_path, dst_fs, dst_path)

def copy(self, src_fs, src_path, dst_fs, dst_path, preserve_time=False):
    # type: (FS, Text, FS, Text, bool) -> None
    """Copy a file from one fs to another."""
    if self.queue is None:
        # This should be the most performant for a single-thread
        copy_file_internal(
            src_fs, src_path, dst_fs, dst_path, preserve_time=self.preserve_time
        )
    else:
        self.all_tasks.append((src_fs, src_path, dst_fs, dst_path))
        src_file = src_fs.openbin(src_path, "r")
        try:
            dst_file = dst_fs.openbin(dst_path, "w")
        except Exception:
            src_file.close()
            raise
        task = _CopyTask(src_file, dst_file)
        self.queue.put(task)

def _translate_glob(pattern, case_sensitive=True):
    levels = 0
    recursive = False
    re_patterns = [""]
    for component in iteratepath(pattern):
        if component == "**":
            re_patterns.append(".*/?")
            recursive = True
        else:
            re_patterns.append(
                "/" + wildcard._translate(component, case_sensitive=case_sensitive)
            )
        levels += 1
    re_glob = "(?ms)^" + "".join(re_patterns) + ("/$" if pattern.endswith("/") else "$")
    return (
        levels,
        recursive,
        re.compile(re_glob, 0 if case_sensitive else re.IGNORECASE),
    )

def _make_iter(self, search="breadth", namespaces=None):
    # type: (str, List[str]) -> Iterator[GlobMatch]
    try:
        levels, recursive, re_pattern = _PATTERN_CACHE[
            (self.pattern, self.case_sensitive)
        ]
    except KeyError:
        levels, recursive, re_pattern = _translate_glob(
            self.pattern, case_sensitive=self.case_sensitive
        )

    for path, info in self.fs.walk.info(
        path=self.path,
        namespaces=namespaces or self.namespaces,
        max_depth=None if recursive else levels,
        search=search,
        exclude_dirs=self.exclude_dirs,
    ):
        if info.is_dir:
            path += "/"
        if re_pattern.match(path):
            yield GlobMatch(path, info)

def __iter__(self):
    # type: () -> Iterator[GlobMatch]
    """Get an iterator of :class:`fs.glob.GlobMatch` objects."""
    return self._make_iter()

def catch_all(cls, func):
    @functools.wraps(func)
    def new_func(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except cls:
            raise
        except Exception as e:
            raise cls(exc=e)

    return new_func  # type: ignore

def new_func(*args, **kwargs):
    try:
        return func(*args, **kwargs)
    except cls:
        raise
    except Exception as e:
        raise cls(exc=e)

def seek(self, offset, whence=SEEK_SET):
    # type: (int, int) -> int
    return self._f.seek(offset, whence)

def seekable(self):
    # type: () -> bool
    try:
        return self._f.seekable()
    except AttributeError:
        try:
            self.seek(0, SEEK_CUR)
        except IOError:
            return False
        else:
            return True

def readinto(self, b):
    # type: (bytearray) -> int
    try:
        return self._f.readinto(b)
    except AttributeError:
        data = self._f.read(len(b))
        bytes_read = len(data)
        b[:bytes_read] = data
        return bytes_read

def readinto1(self, b):
    # type: (bytearray) -> int
    try:
        return self._f.readinto1(b)
    except AttributeError:
        data = self._f.read1(len(b))
        bytes_read = len(data)
        b[:bytes_read] = data
        return bytes_read

def run(self):
    # type () -> None
    queue = self.copier.queue
    while True:
        task = queue.get(block=True)
        try:
            if task is None:
                break  # Sentinel to exit thread
            task()
        except Exception as error:
            self.copier.add_error(error)
        finally:
            queue.task_done()

def __call__(self):
    # type: () -> None
    """Task implementation."""

def add_error(self, error):
    """Add an exception raised by a task."""
    self.errors.append(error)

def start(self):
    """Start the workers."""
    if self.num_workers:
        self.queue = Queue(maxsize=self.num_workers)
        self.workers = [_Worker(self) for _ in range(self.num_workers)]
        for worker in self.workers:
            worker.start()
    self.running = True

def __enter__(self):
    self.start()
    return self

def delegate_fs(self):
    # type: () -> _F
    return self._wrap_fs

def __new__(mcls, classname, bases, cls_dict):
    cls_dict.setdefault("__init__", bases[0].__init__)
    return super(abc.ABCMeta, mcls).__new__(mcls, classname, bases, cls_dict)

def __repr__(self):
    # type: () -> Text
    return "Mode({!r})".format(self._mode)

def __str__(self):
    # type: () -> Text
    return self._mode

def validate(self, _valid_chars=frozenset("rwxtab+")):
    # type: (Union[Set[Text], FrozenSet[Text]]) -> None
    """Validate the mode string.

    Raises:
        ValueError: if the mode contains invalid chars.

    """
    mode = self._mode
    if not mode:
        raise ValueError("mode must not be empty")
    if not _valid_chars.issuperset(mode):
        raise ValueError("mode '{}' contains invalid characters".format(mode))
    if mode[0] not in "rwxa":
        raise ValueError("mode must start with 'r', 'w', 'x', or 'a'")
    if "t" in mode and "b" in mode:
        raise ValueError("mode can't be binary ('b') and text ('t')")

def mode(self):
    # type: () -> int
    """`int`: mode integer."""
    mode = 0
    for name, mask in self._LINUX_PERMS:
        if name in self._perms:
            mode |= mask
    return mode

def make_mode(init):
    # type: (Union[int, Iterable[Text], None]) -> int
    """Make a mode integer from an initial value."""
    return Permissions.get_mode(init)

def create(cls, init=None):
    # type: (Union[int, Iterable[Text], None]) -> Permissions
    """Create a permissions object from an initial value.

    Arguments:
        init (int or list, optional): May be None to use `0o777`
            permissions, a mode integer, or a list of permission names.

    Returns:
        int: mode integer that may be used for instance by `os.makedir`.

    Example:
        >>> Permissions.create(None)
        Permissions(user='rwx', group='rwx', other='rwx')
        >>> Permissions.create(0o700)
        Permissions(user='rwx', group='', other='')
        >>> Permissions.create(['u_r', 'u_w', 'u_x'])
        Permissions(user='rwx', group='', other='')

    """
    if init is None:
        return cls(mode=0o777)
    if isinstance(init, cls):
        return init
    if isinstance(init, int):
        return cls(mode=init)
    if isinstance(init, list):
        return cls(names=init)
    raise ValueError("permissions is invalid")

def __get__(self, obj, obj_type=None):
    # type: (Permissions, Optional[Type[Permissions]]) -> bool
    return self._name in obj

def __set__(self, obj, value):
    # type: (Permissions, bool) -> None
    if value:
        obj.add(self._name)
    else:
        obj.remove(self._name)

def __iter__(self):
    # type: () -> Iterator[Text]
    return iter(self._perms)

def __contains__(self, permission):
    # type: (object) -> bool
    return permission in self._perms

def load(cls, permissions):
    # type: (List[Text]) -> Permissions
    """Load a serialized permissions object."""
    return cls(names=permissions)

def copy(self):
    # type: () -> Permissions
    """Make a copy of this permissions object."""
    return Permissions(names=list(self._perms))

def as_str(self):
    # type: () -> Text
    """Get a Linux-style string representation of permissions."""
    perms = [
        c if name in self._perms else "-"
        for name, c in zip(self._LINUX_PERMS_NAMES[-9:], "rwxrwxrwx")
    ]
    if "setuid" in self._perms:
        perms[2] = "s" if "u_x" in self._perms else "S"
    if "setguid" in self._perms:
        perms[5] = "s" if "g_x" in self._perms else "S"
    if "sticky" in self._perms:
        perms[8] = "t" if "o_x" in self._perms else "T"

    perm_str = "".join(perms)
    return perm_str

def _check(perm, name):
    # type: (Text, Text) -> Text
    return name if perm in self._perms else ""

def __repr__(self):
    # type: () -> Text
    return "<fs-registry {!r}>".format(self.protocols)

def protocols(self):
    # type: () -> List[Text]
    """`list`: the list of supported protocols."""
    _protocols = list(self._protocols)
    if self.load_extern:
        _protocols.extend(
            entry_point.name
            for entry_point in pkg_resources.iter_entry_points("fs.opener")
        )
        _protocols = list(collections.OrderedDict.fromkeys(_protocols))
    return _protocols

def get_opener(self, protocol):
    # type: (Text) -> Opener
    """Get the opener class associated to a given protocol.

    Arguments:
        protocol (str): A filesystem protocol.

    Returns:
        Opener: an opener instance.

    Raises:
        ~fs.opener.errors.UnsupportedProtocol: If no opener
            could be found for the given protocol.
        EntryPointLoadingError: If the returned entry point
            is not an `Opener` subclass or could not be loaded
            successfully.

    """
    protocol = protocol or self.default_opener

    if self.load_extern:
        entry_point = next(
            pkg_resources.iter_entry_points("fs.opener", protocol), None
        )
    else:
        entry_point = None

    # If not entry point was loaded from the extensions, try looking
    # into the registered protocols
    if entry_point is None:
        if protocol in self._protocols:
            opener_instance = self._protocols[protocol]
        else:
            raise UnsupportedProtocol(
                "protocol '{}' is not supported".format(protocol)
            )

    # If an entry point was found in an extension, attempt to load it
    else:
        try:
            opener = entry_point.load()
        except Exception as exception:
            raise EntryPointError(
                "could not load entry point; {}".format(exception)
            )
        if not issubclass(opener, Opener):
            raise EntryPointError("entry point did not return an opener")

        try:
            opener_instance = opener()
        except Exception as exception:
            raise EntryPointError(
                "could not instantiate opener; {}".format(exception)
            )

    return opener_instance
